def validate_topics(name, topics):
    assert len(topics) == 100, f"Expected 100 topics for {name}, got {len(topics)}"
    seen_titles = set()
    for i, t in enumerate(topics):
        title, subj, sys_name, answer, citation, url = t
        assert title not in seen_titles, f"Duplicate title in {name} #{i+1}: {title}"
        seen_titles.add(title)
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject '{subj}' in {name} #{i+1}: {title}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system '{sys_name}' in {name} #{i+1}: {title}"
        assert len(answer) >= 35, f"Short answer in {name} #{i+1}: {answer}"
        assert len(citation) >= 5, f"Short citation in {name} #{i+1}: {citation}"
        assert url.startswith("https://"), f"Invalid url in {name} #{i+1}: {url}"
    print(f"Validated {len(topics)} {name} topics successfully.")

def main():
    validate_topics("NEET PG", NEET_PG_TOPICS)
    validate_topics("MRCP", MRCP_TOPICS)

    output_path = os.path.join(os.path.dirname(__file__), "mega71_topics_a.py")
    with open(output_path, "w", encoding="utf-8") as f:
        f.write("# scripts/mega71_topics_a.py\n")
        f.write("# Generated automatically\n\n")
        f.write(f"NEET_PG_TOPICS = {repr(NEET_PG_TOPICS)}\n\n")
        f.write(f"MRCP_TOPICS = {repr(MRCP_TOPICS)}\n")
    print(f"Wrote {output_path} successfully.")

if __name__ == "__main__":
    main()
